 865	        guard !trimmedName.isEmpty else {
 866	            return false
 867	        }
 868	        guard trimmedName != draft.initialName else {
 869	            renameDraft = nil
 870	            return true
 871	        }
 872	
 873	        guard store.renameInBackground(draft.row, to: trimmedName) else {
 874	            return false
