1078	    private var dockScreenValue: String {
1079	        switch screenStore.state {
1080	        case .configurationError:
1081	            return "configuration-error"
1082	        case .idle(let hosts):
1083	            return "idle; hosts=\(hosts.count); lens=\(selectedLens.rawValue); filters=\(filterState.activeFilterCount)"
1084	        case .loading(let hosts):
1085	            return "loading; hosts=\(hosts.count); lens=\(selectedLens.rawValue); filters=\(filterState.activeFilterCount)"
1086	        case .loaded(let renderSnapshot):
1087	            let startedAt = Date()
1088	            let snapshot = renderSnapshot.snapshot
1089	            let pinnedCount = renderSnapshot.projection.pinnedRows.count
1090	            let visibleRows = dockAutomationRows(in: renderSnapshot.projection)
1091	            let encodedRowValues = visibleRows
1092	                .map { row in
1093	                    let identifier = AutomationID.Dock.row(hostID: row.hostID, threadID: row.threadID).rawValue
1094	                    return automationEncoded("\(identifier)=\(row.automationValue)")
1095	                }
1096	                .joined(separator: "|")
1097	            let value = "loaded; rows=\(snapshot.rowCount); visibleRows=\(visibleRows.count); pinned=\(pinnedCount); lens=\(selectedLens.rawValue); search=\(!searchText.isEmpty); filters=\(filterState.activeFilterCount); rowValues=\(encodedRowValues); \(activeSummaryText)"
1098	            PerformanceProbe.dockAccessibilityValueBuilt(
1099	                revision: renderSnapshot.revision,
1100	                rowCount: snapshot.rowCount,
1101	                visibleRowCount: visibleRows.count,
1102	                encodedLength: encodedRowValues.count,
1103	                durationMilliseconds: PerformanceProbe.milliseconds(since: startedAt)
1104	            )
1105	            return value
1106	        }
1107	    }
