1109	    private func dockAutomationRows(in projection: DockCardProjection) -> [DockRowViewModel] {
1110	        var rows: [DockRowViewModel] = []
1111	        if !isPinnedCollapsed {
1112	            rows.append(contentsOf: projection.pinnedRows)
1113	        }
1114	        switch selectedLens {
1115	        case .newest:
1116	            rows.append(contentsOf: projection.rows)
1117	        case .host:
1118	            for group in projection.groups where !collapsedHostGroupIDs.contains(group.id) {
1119	                rows.append(contentsOf: group.rows)
1120	            }
1121	        case .branch:
1122	            for group in projection.groups where !collapsedBranchGroupIDs.contains(group.id) {
1123	                rows.append(contentsOf: group.rows)
1124	            }
1125	        }
1126	
1127	        var seen = Set<String>()
1128	        return rows.filter { seen.insert($0.projectionID).inserted }
1129	    }
